/** Maksymalna liczba warstw zasięgu na mapie. */
export const MAX_COVERAGE_LAYERS = 9;

const LANGS = { pl: PL, en: EN };

/** Język jak w i18n.js: base z hass.language, nieobsługiwany -> pl. */
export function plannerLanguage(hass) {
  const raw = (hass && hass.language) || DEFAULT_LANGUAGE;
  const base = String(raw).toLowerCase().split('-')[0];
  return LANGS[base] && STRINGS_LANGS.has(base) ? base : DEFAULT_LANGUAGE;
}

/** Podstawia %1$s / %2$d ... (kolejne argumenty od 1) oraz zamienia %% na %. */
export function formatPlannerString(template, args) {
  return String(template)
    .replace(/%(\d+)\$[sd]/g, (m, n) => {
      const v = args[Number(n) - 1];
      return v === undefined || v === null ? '' : String(v);
    })
    .replace(/%%/g, '%');
}

/**
 * Napis plannera. Klucz bez prefiksu "planner_" (np. 'point_a'), napisy HA mają prefiks 'ha_'.
 * Brak klucza w języku -> polski -> sam klucz (widoczny brak tłumaczenia, jak w i18n.js).
 */
export function ps(hass, key, ...args) {
  const lang = plannerLanguage(hass);
  let text = LANGS[lang][key];
  if (text === undefined) text = PL[key];
  if (text === undefined) return key;
  return args.length ? formatPlannerString(text, args) : formatPlannerString(text, []);
}

/** Wersja z jawnym językiem (testy, eksport bez hass). */
export function psLang(lang, key, ...args) {
  const dict = LANGS[lang] || PL;
  let text = dict[key];
  if (text === undefined) text = PL[key];
  if (text === undefined) return key;
  return formatPlannerString(text, args);
}

export const PLANNER_STRING_KEYS = Object.freeze(Object.keys(PL));
